for(let e of [...enemies,...(boss?[boss]:[])]){if(e.dead)continue;e.age+=dt;e.hurt=Math.max(0,e.hurt-dt);if(e.boss){e.y=Math.min(190,e.y+80*dt);e.x=300+Math.sin(e.age*.7)*150;e.laserClock-=dt;if(e.final&&e.laserClock<0&&e.y>=180){e.laserClock=6;for(let s of [-1,1])hazards.push({x:e.x+s*90,age:0,life:2.2,width:28})}}else{e.y+=e.speed*dt;if(e.path===1)e.x=e.origin+Math.sin(e.age*1.2)*50;if(e.path===2)e.x=e.origin+Math.sin(e.age*1.7)*35;if(e.path===3)e.x=clamp(e.origin+(e.origin<300?1:-1)*Math.sin(e.age*.6)*250,25,575)}e.fire-=dt;if(e.fire<=0){fireEnemy(e);e.fire=e.boss?(e.hp/e.max<.5?.72:1):e.type===2?2.2:4.5}if(dist(e,p)<e.r+12){hit(e);if(!e.boss)kill(e)}}
