for(let m of missiles){m.age+=dt;const e=nearest(m.x,m.y);if(e){const a=Math.atan2(e.y-m.y,e.x-m.x);m.vx+=(Math.cos(a)*480-m.vx)*Math.min(1,dt*7);m.vy+=(Math.sin(a)*480-m.vy)*Math.min(1,dt*7)}else m.vy-=dt*400;m.x+=m.vx*dt;m.y+=m.vy*dt;if(Math.random()<.6)particles.push({x:m.x,y:m.y,vx:0,vy:50,life:.2,max:.2,r:3,color:'#ffc67d'});for(let target of [...enemies,...(boss?[boss]:[])])if(!target.dead&&!m.dead&&dist(m,target)<target.r+8){damage(target,m.d);m.dead=true;ring(m.x,m.y,'#ffc78a',38,.25);particle(m.x,m.y,'#ffc66f',8)}}
for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;const d=dist(b,p);if(d<b.r+8){hit(b);b.dead=true}else if(d<30&&!b.grazed&&p.inv<=0){b.grazed=true;graze++;score+=25;if(graze%5===0)text(p.x,p.y-45,'GRAZE +125','#b6ffed',15)}}
for(let h of hazards){h.age+=dt;h.life-=dt;if(h.age>1.25&&Math.abs(p.x-h.x)<h.width/2+7)hit()}
